using symbol "std:io" @assert; using symbol "std:io" @print;
 function (<-)(a::i64 in O,b::u32)->const i64 in O where {owner O} {intrinsic (<-)(a,i64(b));a}
 ptr a=0,b=0; ptr observed=a <- b <- 7u32; b<-12; a<-13; behave @assert(observed==13 && b==12); behave @print(1);

data Root {id::u64;} data Cell {n::i64;} owned region arena::Root <- make Root(capacity=512u64){id<-1u64};
using symbol "std:io" @assert; using symbol "std:io" @print;
 symbol @bias::i64; effect @bias<-3;
 proc ([]<-)(c::ref<Cell> in O,i::u32,v::i64)->void where {owner O} {deref(c).n<-v+@bias;{}}
 ptr cell=alloc arena Cell(0); {effect @bias<-5;cell[0u32]<-7;}; behave @assert(deref(cell).n==12); behave @print(1);

using symbol "std:io" @assert; using symbol "std:io" @print;
 data Root {id::u64;} symbol @forward::proc(owned region ::Root)->owned region ::Root;
 effect proc @forward(owned region r::Root)->owned region ::Root{r};
 owned region first::Root<-make Root(capacity=64u64){id<-4u64};
 owned region second::Root<-behave @forward(first); behave @assert(root(second).id==4u64); behave @print(1);

data Root {id::u64;} data Cell {n::i64;} owned region arena::Root <- make Root(capacity=512u64){id<-1u64};
function edit(region r::Root,c::ref<Cell> in r)->void {deref(c).n<-1;{}}
 owned region other::Root<-make Root(capacity=64u64){id<-2u64}; ptr cell=alloc arena Cell(0);edit(other,cell);

data Root {id::u64;} data Cell {n::i64;} owned region arena::Root <- make Root(capacity=512u64){id<-1u64};
function (<-)(a::ref<Cell> in O,b::i64)->void where {owner O} {deref(a).n<-b;{}}
 ptr cell=alloc arena Cell(0);ptr n=0;n<- (cell<-2);

data Root {id::u64;} data Cell {n::i64;} owned region arena::Root <- make Root(capacity=512u64){id<-1u64};
function ([]<-)(a::ref<Cell> in O,i::u32,b::i64)->const i64 where {owner O} {b}
 ptr cell=alloc arena Cell(0);cell[0u32]<-2;

data Root {id::u64;} data Cell {n::i64;} owned region arena::Root <- make Root(capacity=512u64){id<-1u64};
function ([]<-)(a::ref<Cell> in O,i::u32,b::i64)->void where {owner O} {}
 function ([]<-)(a::ref<Cell> in O,i::u32,b::i64)->const i64 in O where {owner O} {deref(a).n}
 ptr cell=alloc arena Cell(0);cell[0u32]<-2;

using symbol "std:io" @print;
unit Request;
unit Index;
array Values[u32(Index)]::i64;
conversion function choose(value::u32(Request))::u32(Index) { Index(1u32 / scalar(value)) }
procedure ([]<-)(values::ref<Values> in O1, index::u32(Index*), value::i64)::const i64 in O1 where {owner O1} {
  store(values, index, value);
  values[index]
}
region symbol @arena;
symbol @values :: ref<Values>;
effect @arena <- region(4096u64);
effect @values = alloc @arena Values(1u64, 0);
({ behave @print(11); @values })[{ behave @print(22); Request(0u32) }] <- {
  behave @print(33);
  7
};
